// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: deploy a simple contract that will revert on any external call, so the reference reverts
        // We'll use a dummy address that has no code, so the call will succeed but return false (no revert)
        // Actually, to make the reference revert, we need a contract that reverts on transferFrom
        // Deploy a minimal contract that reverts
        Reverter reverter = new Reverter();
        address[] memory tos = new address[](1);
        tos[0] = address(0x1); // arbitrary, but we'll use the reverter as caddress
        // The reference will call reverter.transferFrom(from, address(0x1), v) which reverts
        // The mutant will not call anything and return true
        // So we wrap in try/catch
        bool ok;
        try c.transfer(address(this), address(reverter), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference should revert (ok = false), the mutant should succeed (ok = true)
        // Assert that the behavior matches the reference: ok == false
        assertTrue(ok == false, "Reference should revert on this input");
    }
}

contract Reverter {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("I always revert");
    }
}

