pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address[] memory tos = new address[](1);
        tos[0] = address(0x1);

        bool ok;
        try c.transfer(address(this), address(this), tos, 0) {
            ok = true;
        } catch {
            ok = false;
        }

        // On the reference, the external call to transferFrom fails (address(this) lacks it), so it reverts -> ok = false.
        // On the mutant, the loop never executes, so it returns true without calling -> ok = true.
        // Assert that the reference behavior is false (revert) — the mutant will fail because it returns true.
        assertTrue(!ok, "Expected revert but got success");
    }
}

