pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract RevertingReceiver {
    fallback() external payable {
        revert("always revert");
    }
}

contract InvMutTest is Test {
    C c;
    RevertingReceiver receiver;

    function setUp() public {
        c = new C();
        receiver = new RevertingReceiver();
    }

    function testRegression_property() public {
        address[] memory tos = new address[](1);
        tos[0] = address(0x1);

        // Call transfer; reference reverts because call to receiver.revert() fails,
        // buggy version loops 0 times and returns true.
        bool ok;
        try c.transfer(address(this), address(receiver), tos, 0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}

