pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple mock token that records the selector called
        TokenMock mock = new TokenMock();
        address alice = address(0xAlice);
        address bob = address(0xBob);
        address[] memory tos = new address[](1);
        tos[0] = bob;

        // Call transfer: reference calls transferFrom, bug calls transfer
        c.transfer(alice, address(mock), tos, 100);

        // Assert that the selector recorded by the mock matches transferFrom (reference behavior)
        // bytes4(keccak256("transferFrom(address,address,uint256)")) = 0x23b872dd
        assertEq(mock.lastCalledSelector(), 0x23b872dd);
    }
}

contract TokenMock {
    bytes4 public lastCalledSelector;
    fallback(bytes calldata data) external returns (bytes memory) {
        lastCalledSelector = bytes4(data[0:4]);
        return abi.encode(true);
    }
}

