pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // deploy a mock token with balance tracking
        MockToken token = new MockToken();
        // transfer
        address[] memory tos = new address[](1);
        tos[0] = address(0xBob);
        c.transfer(address(0xAlice), address(token), tos, 100);
        // the reference's transferFrom increases Bob's balance, bug's transfer does not
        assertTrue(token.balances(address(0xBob)) != 0);
    }
}

contract MockToken {
    mapping(address => uint256) public balances;

    function transferFrom(address, address to, uint256 amount) external returns (bool) {
        balances[to] += amount;
        return true;
    }

    function transfer(address, address, uint256) external pure returns (bool) {
        return false;
    }
}

